// harness v2 (SC-5859) — generated by `harness init`; change the template in ~/Development/harness, never this file
// Screenshot baselines per route × viewport. Snapshots live in harness-baselines.spec.ts-snapshots/
// and are test-locked: an untouched route that changes is a regression; a touched route may
// re-baseline only with the critic's approval (`harness gate baselines`).
import { test, expect } from '@playwright/test';
import { AxeBuilder } from '@axe-core/playwright';
import fs from 'node:fs';
type Route = { path: string; slug: string };
type Viewport = { name: string; width: number; height: number };
const cfg = JSON.parse(fs.readFileSync('.harness/routes.json', 'utf8')) as { routes: Route[]; viewports: Viewport[] };
for (const vp of cfg.viewports) {
  for (const r of cfg.routes) {
    test(`${r.slug} @${vp.name}`, async ({ page }) => {
      await page.setViewportSize({ width: vp.width, height: vp.height });
      const res = await page.goto(r.path);
      expect(res?.status()).toBeLessThan(400);
      await expect(page).toHaveScreenshot(`${r.slug}-${vp.name}.png`, { fullPage: true });
      const axe = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa']).analyze();
      expect(axe.violations.filter((v) => v.impact === 'critical').map((v) => v.id)).toEqual([]);
    });
  }
}
